const payload = $input.first().json.body ?? $input.first().json;
const action = payload.action;

const eventType = payload.issue
  ? (payload.pull_request ? 'pull_request' : 'issue')
  : payload.pull_request
    ? 'pull_request'
    : 'unknown';

const validActions = {
  issue: ['opened', 'edited', 'reopened'],
  pull_request: ['opened', 'synchronize', 'reopened', 'edited']
};

if (!validActions[eventType]?.includes(action)) {
  return [];
}

const repo = payload.repository;
const owner = repo.owner.login;
const repoName = repo.name;
const defaultBranch = repo.default_branch || 'main';

let number, title, description, htmlUrl, labels;
if (eventType === 'issue') {
  number = payload.issue.number;
  title = payload.issue.title;
  description = payload.issue.body || '';
  htmlUrl = payload.issue.html_url;
  labels = (payload.issue.labels || []).map((l) => l.name).join(', ');
} else {
  number = payload.pull_request.number;
  title = payload.pull_request.title;
  description = payload.pull_request.body || '';
  htmlUrl = payload.pull_request.html_url;
  labels = '';
}

const triagePrompt = [
  'Triaging GitHub ' + eventType.replace('_', ' ') + ' #' + number,
  'Repository: ' + owner + '/' + repoName,
  'Action: ' + action,
  'URL: ' + htmlUrl,
  '',
  '## Title',
  title,
  '',
  '## Description',
  description || '(no description provided)',
  labels ? '\n## Labels\n' + labels : '',
  '',
  '## Your task',
  '1. Use the Code Fetcher tool to inspect relevant code (PR diff/files for pull requests; infer likely file paths for issues).',
  '2. Use the Architecture RAG tool to retrieve applicable architecture guidelines.',
  '3. Produce a staff-engineer triage comment in markdown with root cause analysis, suggested fix snippet, compliance score, and next steps.'
].join('\n');

return [{
  json: {
    eventType,
    action,
    owner,
    repo: repoName,
    number,
    title,
    description,
    htmlUrl,
    defaultBranch,
    triagePrompt
  }
}];

const agentOut = $input.first().json;
const event = $('Parse GitHub Event').first().json;

const body = agentOut.output || agentOut.text || agentOut.response || JSON.stringify(agentOut, null, 2);

return [{
  json: {
    owner: event.owner,
    repo: event.repo,
    number: event.number,
    eventType: event.eventType,
    commentBody: body,
    htmlUrl: event.htmlUrl
  }
}];
